129:     var i, link, sheets = WebUtil.getStylesheets();
130:     if (typeof sheet === 'undefined') {
131:         sheet = 'default';
132:     }
133:     for (i=0; i < sheets.length; i += 1) {
134:         link = sheets[i];
135:         if (link.title === sheet) {    
136:             Util.Debug("Using stylesheet " + sheet);
137:             link.disabled = false;
138:         } else {
